            "जरूरत हो तो स्वयं बदलें; हमने पता नहीं बदला है।"
          : "";
    });

    function cardDigits() {
      return $("card").value.replace(/[ -]/g, "");
    }

    function passesLuhn(digits) {
      let sum = 0;
      let double = false;
      for (let i = digits.length - 1; i >= 0; i--) {
        let digit = Number(digits[i]);
        if (double) {
          digit *= 2;
          if (digit > 9) digit -= 9;
        }
        sum += digit;
        double = !double;
      }
      return !/^0+$/.test(digits) && sum % 10 === 0;
    }

    function validExpiry(value) {
      const match = value.trim().match(/^(\d{2})\s*\/?\s*(\d{2}|\d{4})$/);
      if (!match) return false;

      const month = Number(match[1]);
      const year = match[2].length === 2
        ? 2000 + Number(match[2])
        : Number(match[2]);

      if (month < 1 || month > 12) return false;
      const now = new Date();

      // Cards remain valid through their expiry month.
      return year > now.getFullYear() ||
        (year === now.getFullYear() && month >= now.getMonth() + 1);
    }

    function errorFor(id) {
      const value = $(id).value.trim();

      switch (id) {
        case "name":
          return value ? "" : "अपना पूरा नाम भरें।";
        case "email":
          if (!value) return "टिकट पाने के लिए ईमेल भरें।";
          return $("email").validity.typeMismatch
            ? "ईमेल का प्रारूप जाँचें, जैसे name@example.com।"
            : "";
        case "card": {
          const digits = cardDigits();
          return /^\d{12,19}$/.test(digits) && passesLuhn(digits)
            ? ""
            : "कार्ड नंबर जाँचें: 12–19 अंक; केवल spaces या hyphens अतिरिक्त रखें।";
        }
        case "exp":
          return validExpiry(value)
            ? ""
            : "मान्य, गैर-समाप्त महीना/वर्ष भरें; जैसे MM/YY या MMYY।";
        case "cvc":
          return /^\d{3,4}$/.test(value)
            ? ""
            : "कार्ड का 3 या 4 अंकों वाला सुरक्षा कोड भरें।";
        case "captcha":
          return value.toUpperCase() === "M7Q4"
            ? ""
            : "ऊपर दिया demo code M7Q4 भरें; copy/paste भी कर सकते हैं।";
        default:
          return "";
      }
    }

    function validate() {
      $("name").value = $("name").value.trim();
      $("email").value = $("email").value.trim();
      const list = $("error-list");
      list.replaceChildren();
      let count = 0;

      for (const id of fieldIds) {
        const message = errorFor(id);
        const input = $(id);
        const error = $(`${id}-error`);

        error.textContent = message;
        error.hidden = !message;

        if (message) {
          count++;
          input.setAttribute("aria-invalid", "true");

          const item = document.createElement("li");
          const link = document.createElement("a");
          link.href = `#${id}`;
          link.textContent = `${labels[id]}: ${message}`;
          link.addEventListener("click", event => {
            event.preventDefault();
            input.focus();
          });
          item.append(link);
          list.append(item);
        } else {
          input.removeAttribute("aria-invalid");
        }
      }

      $("errors").hidden = count === 0;
      if (count) $("errors").focus();
      return count === 0;
    }

    form.addEventListener("submit", event => {
      event.preventDefault();
      if (!validate()) return;

      // Use textContent, not HTML interpolation, for user-supplied values.
      $("review-name").textContent = $("name").value;
      $("review-email").textContent = $("email").value;
      $("review-phone").textContent = $("phone").value.trim() || "नहीं दिया";
      $("review-card").textContent = `अंतिम चार अंक: ${cardDigits().slice(-4)}`;
      $("review-news").textContent = $("news").checked
        ? "हाँ — स्वैच्छिक opt-in"
        : "नहीं";

